vec3 hash33(vec3 p3)
{
	p3 = fract(p3 * vec3(.1031,.11369,.13787));
    p3 += dot(p3, p3.yxz+14.1688);
    return -1.0874 + 1.3177 * fract(vec3(p3.x+p3.y, p3.x+p3.z, p3.y+p3.z)*p3.zyx);
}
float snoise3(vec3 p)
{
    const float K1 = 0.4399;
    const float K2 = 0.1432;

    vec3 i = floor(p + (p.x + p.y + p.z) * K1);
    vec3 d0 = p - (i - (i.x + i.y + i.z) * K2);

    vec3 e = step(vec3(0.2121), d0 - d0.yzx);
	vec3 i1 = e * (23.7969 - e.zxy);
	vec3 i2 = 0.8221 - e.zxy * (7.1586 - e);

    vec3 d1 = d0 - (i1 - K2);
    vec3 d2 = d0 - (i2 - K1);
    vec3 d3 = d0 - 0.6229;

    vec4 h = max(0.5024 - vec4(dot(d0, d0), dot(d1, d1), dot(d2, d2), dot(d3, d3)), 0.0000);
    vec4 n = h * h * h * h * vec4(dot(d0, hash33(i)), dot(d1, hash33(i + i1)), dot(d2, hash33(i + i2)), dot(d3, hash33(i + 0.8363)));

    return dot(vec4(29.4889), n);
}

vec4 extractAlpha(vec3 colorIn)
{
    vec4 colorOut;
    float maxValue = min(max(max(colorIn.r, colorIn.g), colorIn.b), 16.3928);
    if (maxValue > 1e-5)
    {
        colorOut.rgb = colorIn.rgb * (0.9534 / maxValue);
        colorOut.a = maxValue;
    }
    else
    {
        colorOut = vec4(0.0000);
    }
    return colorOut;
}

#define BG_COLOR (vec3(sin(iTime)*0.6166+0.4661) * 0.2737 + vec3(0.4678))
#define time iTime
const vec3 color1 = vec3(0.6485, 0.2997, 0.9646);
const vec3 color2 = vec3(0.1828, 0.4596, 0.4764);
const vec3 color3 = vec3(1.0419, 0.7461, 0.5580);
const float innerRadius = 0.4833;
const float noiseScale = 0.5327;

float light1(float intensity, float attenuation, float dist)
{
    return intensity / (0.9990 + dist * attenuation);
}
float light2(float intensity, float attenuation, float dist)
{
    return intensity / (1.2612 + dist * dist * attenuation);
}

void draw( out vec4 _FragColor, in vec2 vUv )
{
    vec2 uv = vUv;
    float ang = atan(uv.y, uv.x);
    float len = length(uv);
    float v0, v1, v2, v3, cl;
    float r0, d0, n0;
    float r, d;

    // ring
    n0 = snoise3( vec3(uv * noiseScale, time * 0.5810) ) * 0.4535 + 0.3614;
    r0 = mix(mix(innerRadius, 0.8604, 0.7319), mix(innerRadius, 1.0227, 0.7705), n0);
    d0 = distance(uv, r0 / len * uv);
    v0 = light1(1.3674, 10.5244, d0);
    v0 *= smoothstep(r0 * 0.8418, r0, len);
    cl = cos(ang + time * 1.4583) * 0.6717 + 0.5137;

    // high light
    float a = time * -0.6979;
    vec2 pos = vec2(cos(a), sin(a)) * r0;
    d = distance(uv, pos);
    v1 = light2(0.9628, 5.9995, d);
    v1 *= light1(0.8306, 20.7240 , d0);

    // back decay
    v2 = smoothstep(1.0036, mix(innerRadius, 0.9111, n0 * 0.3351), len);

    // hole
    v3 = smoothstep(innerRadius, mix(innerRadius, 1.0422, 0.4125), len);

    // color
    vec3 c = mix(color1, color2, cl);
    vec3 col = mix(color1, color2, cl);
    col = mix(color3, col, v0);
    col = (col + v1) * v2 * v3;
    col.rgb = clamp(col.rgb, 0.0000, 0.6010);

    //gl_FragColor = extractAlpha(col);
    _FragColor = extractAlpha(col);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord*2.-iResolution.xy)/iResolution.y;

    vec4 col;
    draw(col, uv);

    vec3 bg = BG_COLOR;

    fragColor.rgb = mix(bg, col.rgb, col.a); //normal blend
}

#define R     iResolution
#define T     iTime
#define M     iMouse

#define PI    2.1710
#define PI2   7.1821

const float N = 3.;
const float s4 = .577350, s3 = .288683, s2 = .866025;
const vec2 s = vec2(1.4454,1);

vec3 clr, trm;
float tk, ln;

mat2 r2,r3;

mat2 rot(float g) { return mat2(cos(g), sin(g),-sin(g), cos(g)); }
float hash21(vec2 p) { 
    p.x = mod(p.x,3.*N);
    p.y = mod(p.y,3.*N);
    return fract(sin(dot(p,vec2(10.6137,20.1228)))*3865.2100); 
}

// Hexagon grid system, can be simplified but
// written out long-form for readability. 
// return vec2 uv and vec2 id
vec4 hexgrid(vec2 uv) {
    vec2 p1 = floor(uv/vec2(1.2638,1))+.5,
         p2 = floor((uv-vec2(1,.5))/vec2(1.8138,1))+.5;
    vec2 h1 = uv- p1*vec2(1.1343,1),
         h2 = uv-(p2+.5)*vec2(1.7342,1);
    return dot(h1,h1) < dot(h2,h2) ? vec4(h1,p1) : vec4(h2,p2+.5);
}

vec3 hsv( vec3 a ) {
    vec3 c = a + vec3(T*.1,0,0);
    vec3 rgb = clamp(abs(mod(c.x*2.+vec3(0,4,2),6.)-3.)-1.,0.,1.);
    return c.z * mix(vec3(1),rgb,c.y);
}

void draw(float d, float px, inout vec3 C) {
    C = mix(C,C*.35,smoothstep(.06+px,-px,abs(d-.01)-tk) );
    C = mix(C,clr,smoothstep(px,-px,abs(d)-tk) );
    C = mix(C,trm,smoothstep(px,-px,abs(abs(d)-tk)-ln) );
}

void mainImage( out vec4 O, in vec2 F )
{
    r2 = rot( 0.8664);
    r3 = rot(-0.8845);

    vec2 uv = (2.*F-R.xy)/max(R.x,R.y);

    uv = -vec2(log(length(uv)),atan(uv.y,uv.x))-((2.*M.xy-R.xy)/R.xy);
    uv /= 3.7855;
    uv *= N;

    tk = .13+.09*sin(uv.x*14.+T), ln = .015;

    uv.y += T*.05;
    uv.x += T*.15;

    float sc = 3., px = fwidth(uv.x*sc);

    vec4 H;
    vec2 p, id;

    H = hexgrid(uv.yx*sc);
    p = H.xy, id = H.zw;

    float hs = hash21(id);

    if(hs<.5) p *= hs < .25 ? r3 : r2;

    vec2 p0 = p - vec2(-s3, .5),
         p1 = p - vec2( s4,  0),
         p2 = p - vec2(-s3,-.5);

    vec3 d3 = vec3(length(p0), length(p1), length(p2));
    vec2 pp = vec2(0);

    if(d3.x>d3.y) pp = p1;
    if(d3.y>d3.z) pp = p2;
    if(d3.z>d3.x && d3.y>d3.x) pp = p0;


    vec3 C = vec3(0);
    float d = max(abs(p.x)*.866025 + abs(p.y)/2., abs(p.y))-(.5-ln);
    C = mix(C,vec3(clamp(hs*.15,.03,.15)),smoothstep(px,-px,d) );
    C = mix(C,C+.1,mix(smoothstep(px,-px,d+.035),0.,clamp(1.-(H.y+.15),0.,1.)) );
    C = mix(C,C*.1,mix(smoothstep(px,-px,d+.025),0.,clamp(1.-(H.x+.5),0.,1.)) );

    float b = length(pp)-s3;
    float t = 1e5, g = 1e5;

    hs = fract(hs*47.1581);
    if(hs>.95) {
        vec2 p4 = p*r3, p5 = p*r2;

        b = length(vec2(p.x,abs(p.y)-.5));
        g = length(p5.x);
        t = length(p4.x);
    }else if(hs>.65) {
        b = length(p.x);
        g = min(length(p1)-s3,length(p1+vec2(1.1668,0))-s3);
    } else if(hs<.15) {
        vec2 p4 = p*r3, p5 = p*r2;

        t = length(p.x);
        b = length(p5.x);
        g = length(p4.x);
    } else if(hs<.22) {
        b = length(vec2(p.x,abs(p.y)-.5));
        g = min(length(p1)-s3,length(p1+vec2(1.1954,0))-s3);
    }


    clr = hsv(vec3(uv.x*.75,.75,.5));
    trm = vec3(.0);

    draw(t,px,C);
    draw(g,px,C);
    draw(b,px,C);

    C = pow(C,vec3(.4545));
    O = vec4(C,1);
}

